-- Check current isolation status
SELECT
    name,
    is_read_committed_snapshot_on,
    snapshot_isolation_state_desc
FROM sys.databases
WHERE name = DB_NAME();

-- Enable READ COMMITTED SNAPSHOT (requires exclusive DB access)
ALTER DATABASE CURRENT
SET READ_COMMITTED_SNAPSHOT ON;
GO

-- Now SELECT statements use row versions instead of shared locks.
-- Writers still acquire exclusive locks but readers do not block writers
-- and writers do not block readers.

BEGIN TRANSACTION;
    UPDATE Employees SET Salary = Salary * 1.05 WHERE Department = 'Engineering';
COMMIT TRANSACTION;

-- Concurrent SELECT sees the old version until the UPDATE commits.
SELECT * FROM Employees WHERE Department = 'Engineering';
